def load() -> pd.DataFrame:
    import glob, pandas as pd, os
    paths = glob.glob('data/environment/input/water-body-testing-2023.csv')
    if not paths:
        return pd.DataFrame([{'found_2023_file': False, 'paths': None}])
    df = pd.read_csv(paths[0])
    return pd.concat([df.head(3), df.tail(3)])

def load() -> pd.DataFrame:
    import glob, pandas as pd, os
    paths = glob.glob('data/environment/input/water-body-testing-*.csv')
    rows = []
    for p in sorted(paths)[:5]:
        df = pd.read_csv(p)
        rows.append({'path': p, 'nrows': len(df), 'min_year': df['Year'].min(), 'max_year': df['Year'].max()})
    return pd.DataFrame(rows)

